import copy
rows = [{"id": 2, "name": "B"}, {"id": 1, "name": "A"}]
original = copy.deepcopy(rows)
assert list(import_rows(rows)) == [2, 1]
assert import_rows(rows) == {2: rows[0], 1: rows[1]}
assert rows == original
assert import_rows([]) == {}
for invalid in [[{"id": 1, "name": "A"}, {"id": 1, "name": "B"}], [{"id": 1}], [{"id": "1", "name": "A"}], [{"id": True, "name": "A"}], [{"id": 1, "name": None}]]:
    before = copy.deepcopy(invalid)
    try:
        import_rows(invalid)
    except ValueError:
        pass
    else:
        raise AssertionError("accepted invalid import")
    assert invalid == before

reference.importer.py:
def import_rows(rows: list[dict]) -> dict:
    result = {}
    for row in rows:
        if type(row.get("id")) is not int or not isinstance(row.get("name"), str):
            raise ValueError("invalid record")
        if row["id"] in result:
            raise ValueError("duplicate id")
        result[row["id"]] = dict(row)
    return result

