class Cache:
    def __init__(self, loader):
        self.loader = loader
        self.values = {}

    def get(self, tenant: str, key: str):
        if key not in self.values:
            self.values[key] = self.loader(tenant, key)
        return self.values[key]

repair.checks:
from cache import Cache
calls = []
def load(tenant, key):
    calls.append((tenant, key))
    return None if key == "missing" else (tenant, key)
c = Cache(load)
for tenant, key in [("alice", "settings"), ("bob", "settings"), ("a:b", "c"), ("a", "b:c"), ("", ""), ("alice", "missing")]:
    expected = None if key == "missing" else (tenant, key)
    assert c.get(tenant, key) == expected, "repair: pair identity collision"
    assert c.get(tenant, key) == expected, "repair: pair identity collision"
assert len(calls) == 6
attempts = []
def flaky(tenant, key):
    attempts.append(1)
    if len(attempts) == 1:
        raise RuntimeError("retry")
    return 42
c = Cache(flaky)
try:
    c.get("a", "b")
except RuntimeError:
    pass
else:
    raise AssertionError("swallowed loader failure")
assert c.get("a", "b") == 42 and len(attempts) == 2

